请对以下 case 进行三维加权评分。

=== case_id ===
Case-20-notif-aggregate-014

=== 用户原始指令 (query.txt) ===
快被各种截止日期搞疯了,想要个通知聚合卡片,左侧主视觉用柔和磨砂质感,分隔线分块,每块"距离X还有N分钟/天",比如"距离会议还有15分钟"、"距离作业提交还有2天"(从日历读的),点能跳歌单听首歌冷静下,几小时内要处理的标黄提醒,夜晚感渐变,纵向排列,可以用通知/日历/音乐库里的图标

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "快被各种截止日期搞疯了,想要个通知聚合卡片,左侧主视觉用柔和磨砂质感,分隔线分块,每块\"距离X还有N分钟/天\",比如\"距离会议还有15分钟\"、\"距离作业提交还有2天\"(从日历读的),点能跳歌单听首歌冷静下,几小时内要处理的标黄提醒,夜晚感渐变,纵向排列,可以用通知/日历/音乐库里的图标",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "",
        "abilityName": "",
        "uri": "hwmusic://com.huawei.hmsapp.music/showMusicList?code=a001&type=4"
      }
    }
  ],
  "dataModelSchema": {
    "data": {
      "calendar": {
        "items": [
          {
            "entityId": {
              "type": "string",
              "description": "日历事件唯一标识，可用于查看或关联事件。",
              "sampleValue": "calendar-event-001"
            },
            "title": {
              "type": "string",
              "description": "日历事件短标题，用于组成距离对象名称。",
              "sampleValue": "会议"
            },
            "description": {
              "type": "string",
              "description": "距离该日历事件的剩余时间展示文本。",
              "sampleValue": "还有15分钟"
            },
            "dtStart": {
              "type": "string",
              "description": "事件开始时间，作为日历能力返回的时间参考。",
              "sampleValue": "21:30"
            }
          },
          {
            "entityId": {
              "type": "string",
              "description": "第二条日历事件唯一标识。",
              "sampleValue": "calendar-event-002"
            },
            "title": {
              "type": "string",
              "description": "第二条日历事件短标题，用于组成距离对象名称。",
              "sampleValue": "作业提交"
            },
            "description": {
              "type": "string",
              "description": "距离第二条日历事件的剩余时间展示文本。",
              "sampleValue": "还有2天"
            },
            "dtStart": {
              "type": "string",
              "description": "第二条事件开始时间，作为日历能力返回的时间参考。",
              "sampleValue": "周六"
            }
          }
        ]
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/icon_schedule.png",
      "description": "日程图标，适合用于通知聚合、当下日程和截止日期提醒的主视觉识别。"
    }
  ]
}

